/// Checks the action record against the unrefined Core (docs/spec.md §3.8.9).
#[derive(Debug)]
pub struct Acceptor {
    s: S,
}

impl Acceptor {
    pub fn new(config: Config) -> Result<Acceptor, StepError> {
        Ok(Acceptor { s: initial(&config)? })
    }

    /// The state, for tests.
    pub fn state(&self) -> &S {
        &self.s
    }

    /// The state, for tests that start from another initial state.
    #[doc(hidden)]
    pub fn state_mut(&mut self) -> &mut S {
        &mut self.s
    }

    pub fn accept(&mut self, entry: &Entry) -> Result<(), Reject> {
        match entry {
            Entry::Action(Action::Drop(a0)) => {
                let e5 = match5(&self.s, a0).map_err(Reject::Step)?;
                let found = [e5.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e5 {
                    return fire5(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Action(Action::Start(a0)) => {
                let e6 = match6(&self.s, a0).map_err(Reject::Step)?;
                let found = [e6.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e6 {
                    return fire6(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Action(Action::Tell(a0, a1)) => {
                let e4 = match4(&self.s, a0, a1).map_err(Reject::Step)?;
                let found = [e4.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e4 {
                    return fire4(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Finish(a0)) => {
                let e2 = match2(&self.s, a0).map_err(Reject::Step)?;
                let found = [e2.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e2 {
                    return fire2(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Finish2(a0, a1)) => {
                let e3 = match3(&self.s, a0, a1).map_err(Reject::Step)?;
                let found = [e3.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e3 {
                    return fire3(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Need(a0, a1)) => {
                let e1 = match1(&self.s, a0, a1).map_err(Reject::Step)?;
                let found = [e1.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e1 {
                    return fire1(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Open(a0)) => {
                let e0 = match0(&self.s, a0).map_err(Reject::Step)?;
                let found = [e0.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e0 {
                    return fire0(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
        }
    }
}

fn enc_Key(v: &Key, out: &mut Vec<u8>) {
    codec::nat(*(&v.kn), out);
    codec::len((&v.kv).len(), out);
    for x1 in (&v.kv).iter() {
        enc_Val(x1, out);
    }
}

fn dec_Key(r: &mut codec::Rd<'_>) -> Result<Key, DecodeError> {
    Ok(Key { kn: r.nat()?, kv: { let n = r.len()?; let mut l = Vec::new(); for _ in 0..n { l.push(dec_Val(r)?); } l } })
}

fn enc_Phase(v: &Phase, out: &mut Vec<u8>) {
    codec::nat(match v {
        Phase::Free => 0,
        Phase::Queued => 1,
        Phase::Running => 2,
        Phase::Waiting => 3,
        Phase::Done => 4,
    }, out);
}

fn dec_Phase(r: &mut codec::Rd<'_>) -> Result<Phase, DecodeError> {
    match r.nat()? {
        0 => Ok(Phase::Free),
        1 => Ok(Phase::Queued),
        2 => Ok(Phase::Running),
        3 => Ok(Phase::Waiting),
        4 => Ok(Phase::Done),
        _ => Err(DecodeError("a constructor index")),
    }
}

fn enc_Val(v: &Val, out: &mut Vec<u8>) {
    codec::nat(*(&v.va), out);
    codec::nat(*(&v.vb), out);
}

fn dec_Val(r: &mut codec::Rd<'_>) -> Result<Val, DecodeError> {
    Ok(Val { va: r.nat()?, vb: r.nat()? })
}

/// The bytes of an entry (docs/spec.md §3.8.10).
pub fn encode(entry: &Entry, out: &mut Vec<u8>) {
    match entry {
        Entry::Event(Event::Finish(a0)) => {
            out.push(0);
            codec::nat(0, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Event(Event::Finish2(a0, a1)) => {
            out.push(0);
            codec::nat(1, out);
            codec::nat(i128::from((a0).0), out);
            codec::nat(i128::from((a1).0), out);
        }
        Entry::Event(Event::Need(a0, a1)) => {
            out.push(0);
            codec::nat(2, out);
            codec::nat(i128::from((a0).0), out);
            codec::nat(i128::from((a1).0), out);
        }
        Entry::Event(Event::Open(a0)) => {
            out.push(0);
            codec::nat(3, out);
            codec::nat(*(a0), out);
        }
        Entry::Action(Action::Drop(a0)) => {
            out.push(1);
            codec::nat(0, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Action(Action::Start(a0)) => {
            out.push(1);
            codec::nat(1, out);
            codec::nat(i128::from((a0).0), out);
        }
        Entry::Action(Action::Tell(a0, a1)) => {
            out.push(1);
            codec::nat(2, out);
            codec::nat(i128::from((a0).0), out);
            codec::nat(i128::from((a1).0), out);
        }
    }
}

/// The entry of some bytes (§3.8.10).
pub fn decode(bytes: &[u8]) -> Result<Entry, DecodeError> {
    let mut r = codec::Rd { b: bytes, p: 0 };
    let r = &mut r;
    let side = r.byte()?;
    let code = r.nat()?;
    let e = match (side, code) {
        (0, 0) => Entry::Event(Event::Finish(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (0, 1) => Entry::Event(Event::Finish2(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?), Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (0, 2) => Entry::Event(Event::Need(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?), Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (0, 3) => Entry::Event(Event::Open(r.nat()?)),
        (1, 0) => Entry::Action(Action::Drop(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (1, 1) => Entry::Action(Action::Start(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        (1, 2) => Entry::Action(Action::Tell(Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?), Task(u32::try_from(r.nat()?).map_err(|_| DecodeError("an id"))?))),
        _ => return Err(DecodeError("a label")),
    };
    if !r.done() {
        return Err(DecodeError("trailing bytes"));
    }
    Ok(e)
}

fn ixmem_telling(s: &S, v: Task) -> Result<bool, StepError> {
    Ok(((((&s.st)).get(&v.clone()) == Phase::Done) && !s.waiters.is_empty((v.clone()).0)))
}

fn ixbound_telling(s: &S) -> Result<i128, StepError> {
    Ok(s.nt.clone())
}

fn ixfirst_telling(s: &S) -> Result<Task, StepError> {
    s.ix_telling.front(0).map(|(_, v)| Task(v)).ok_or(StepError::Undefined("first(telling)"))
}

fn ixsome_telling(s: &S) -> Result<bool, StepError> {
    Ok(s.ix_telling.front(0).is_some())
}

fn ixrefresh_telling(s: &mut S, v: u32) -> Result<(), StepError> {
    let n = Task(v);
    if ixmem_telling(s, n)? {
        let (c, k) = (0, s.ix_telling.stamp(v)?);
        s.ix_telling.refresh(v, c, k)
    } else {
        s.ix_telling.remove(v);
        Ok(())
    }
}

fn ixmem_droppable(s: &S, v: Task) -> Result<bool, StepError> {
    Ok(((((&s.st)).get(&v.clone()) == Phase::Done) && s.waiters.is_empty((v.clone()).0)))
}

fn ixbound_droppable(s: &S) -> Result<i128, StepError> {
    Ok(s.nt.clone())
}

fn ixfirst_droppable(s: &S) -> Result<Task, StepError> {
    s.ix_droppable.front(0).map(|(_, v)| Task(v)).ok_or(StepError::Undefined("first(droppable)"))
}

fn ixsome_droppable(s: &S) -> Result<bool, StepError> {
    Ok(s.ix_droppable.front(0).is_some())
}

fn ixrefresh_droppable(s: &mut S, v: u32) -> Result<(), StepError> {
    let n = Task(v);
    if ixmem_droppable(s, n)? {
        let (c, k) = (0, s.ix_droppable.stamp(v)?);
        s.ix_droppable.refresh(v, c, k)
    } else {
        s.ix_droppable.remove(v);
        Ok(())
    }
}

fn ixmem_queue(s: &S, v: Task) -> Result<bool, StepError> {
    Ok((((&s.st)).get(&v.clone()) == Phase::Queued))
}

fn ixkey_queue(s: &S, v: Task) -> Result<Vec<i128>, StepError> {
    Ok(((&s.rank)).get(&v.clone()))
}

fn ixbound_queue(s: &S) -> Result<i128, StepError> {
    Ok(s.nt.clone())
}

fn ixfirst_queue(s: &S) -> Result<Task, StepError> {
    s.ix_queue.front(0).map(|(_, v)| Task(v)).ok_or(StepError::Undefined("first(queue)"))
}

fn ixsome_queue(s: &S) -> Result<bool, StepError> {
    Ok(s.ix_queue.front(0).is_some())
}

fn ixrefresh_queue(s: &mut S, v: u32) -> Result<(), StepError> {
    let n = Task(v);
    if ixmem_queue(s, n)? {
        let (c, k) = (0, ixkey_queue(s, n)?);
        s.ix_queue.refresh(v, c, k)
    } else {
        s.ix_queue.remove(v);
        Ok(())
    }
}

/// The indexes refreshed at the ids the last summand wrote, in ascending order
/// (docs/spec.md §3.8.3).
fn refresh(s: &mut S) -> Result<(), StepError> {
    let d: BTreeSet<u32> = std::mem::take(&mut s.dirty_Task).into_iter().collect();
    for v in d {
        ixrefresh_telling(s, v)?;
        ixrefresh_droppable(s, v)?;
        ixrefresh_queue(s, v)?;
    }
    Ok(())
}

fn stepper_init(s: &mut S) -> Result<(), StepError> {
    s.ix_telling = Ix::new(3, 1);
    s.ix_droppable = Ix::new(2, 1);
    s.ix_queue = Ix::new(1, 1);
    let b = u32::try_from(ixbound_telling(s)?).map_err(|_| StepError::Overflow("bound"))?;
    for v in 0..b {
        ixrefresh_telling(s, v)?;
    }
    let b = u32::try_from(ixbound_droppable(s)?).map_err(|_| StepError::Overflow("bound"))?;
    for v in 0..b {
        ixrefresh_droppable(s, v)?;
    }
    let b = u32::try_from(ixbound_queue(s)?).map_err(|_| StepError::Overflow("bound"))?;
    for v in 0..b {
        ixrefresh_queue(s, v)?;
    }
    Ok(())
}

// c_open
fn match_s0(s: &S, a0: &i128) -> Result<Option<(i128, )>, StepError> {
    let v_k = a0.clone();
    if !(((v_k.clone() < 4i128) && ((s.nt.clone() < s.cap.clone()) && (((&s.made)).get(&m_keyof(v_k.clone())?) == 0i128)))) {
        return Ok(None);
    }
    Ok(Some((v_k, )))
}

fn fire_s0(s: &mut S, env: (i128, )) -> Result<(), StepError> {
    let (v_k, ) = env;
    let n_nt = rt::add(s.nt.clone(), 1i128)?;
    let mut o_label = Ov::over(&s.label);
    o_label.set(Task(rt::id(s.nt.clone())?), v_k.clone());
    let w_label = o_label.writes();
    let mut o_st = Ov::over(&s.st);
    o_st.set(Task(rt::id(s.nt.clone())?), Phase::Queued);
    let w_st = o_st.writes();
    let mut o_rank = Ov::over(&s.rank);
    o_rank.set(Task(rt::id(s.nt.clone())?), m_rankof(v_k.clone(), s.nt.clone())?);
    let w_rank = o_rank.writes();
    let mut o_made = Ov::over(&s.made);
    o_made.set(m_keyof(v_k.clone())?, rt::add(s.nt.clone(), 1i128)?);
    let w_made = o_made.writes();
    for (k, v) in w_label {
        s.label.set(k, rt::fit(v, 0, 4294967295, "label")?);
    }
    for (k, v) in w_st {
        s.dirty_Task.push(k.0);
        s.st.set(k, v);
    }
    for (k, v) in w_rank {
        s.dirty_Task.push(k.0);
        s.rank.set(k, v);
    }
    for (k, v) in w_made {
        s.made.set(k, rt::fit(v, 0, 4294967295, "made")?);
    }
    s.nt = rt::fit(n_nt, 0, 4294967295, "nt")?;
    Ok(())
}

// c_need
fn match_s1(s: &S, a0: &Task, a1: &Task) -> Result<Option<(Task, Task, )>, StepError> {
    let v_x = a0.clone();
    let v_y = a1.clone();
    if !(((((&s.st)).get(&v_x.clone()) == Phase::Running) && ((v_x.clone() != v_y.clone()) && ((i128::from((v_y.clone()).0) < s.nt.clone()) && (((&s.st)).get(&v_y.clone()) != Phase::Free))))) {
        return Ok(None);
    }
    Ok(Some((v_x, v_y, )))
}

fn fire_s1(s: &mut S, env: (Task, Task, )) -> Result<(), StepError> {
    let (v_x, v_y, ) = env;
    let mut o_st = Ov::over(&s.st);
    o_st.set(v_x.clone(), Phase::Waiting);
    let w_st = o_st.writes();
    let mut a_waiters: Vec<AdjOp<Task>> = Vec::new();
    a_waiters.push(AdjOp::Push((v_y.clone()).0, v_x.clone()));
    let mut o_missing = Ov::over(&s.missing);
    o_missing.set(v_x.clone(), rt::add(((&s.missing)).get(&v_x.clone()), 1i128)?);
    let w_missing = o_missing.writes();
    for op in a_waiters {
        s.dirty_Task.push(op.id());
        s.waiters.apply(op)?;
    }
    for (k, v) in w_st {
        s.dirty_Task.push(k.0);
        s.st.set(k, v);
    }
    for (k, v) in w_missing {
        s.missing.set(k, rt::fit(v, 0, 4294967295, "missing")?);
    }
    Ok(())
}

// c_finish
fn match_s2(s: &S, a0: &Task) -> Result<Option<(Task, )>, StepError> {
    let v_x = a0.clone();
    if !((((&s.st)).get(&v_x.clone()) == Phase::Running)) {
        return Ok(None);
    }
    Ok(Some((v_x, )))
}

fn fire_s2(s: &mut S, env: (Task, )) -> Result<(), StepError> {
    let (v_x, ) = env;
    let mut o_st = Ov::over(&s.st);
    o_st.set(v_x.clone(), Phase::Done);
    let w_st = o_st.writes();
    for (k, v) in w_st {
        s.dirty_Task.push(k.0);
        s.st.set(k, v);
    }
    Ok(())
}

// c_finish2
fn match_s3(s: &S, a0: &Task, a1: &Task) -> Result<Option<(Task, Task, )>, StepError> {
    let v_x = a0.clone();
    let v_y = a1.clone();
    if !(((((&s.st)).get(&v_x.clone()) == Phase::Running) && ((((&s.st)).get(&v_y.clone()) == Phase::Running) && (i128::from((v_x.clone()).0) < i128::from((v_y.clone()).0))))) {
        return Ok(None);
    }
    Ok(Some((v_x, v_y, )))
}

fn fire_s3(s: &mut S, env: (Task, Task, )) -> Result<(), StepError> {
    let (v_x, v_y, ) = env;
    let mut o_st = Ov::over(&s.st);
    o_st.set(v_x.clone(), Phase::Done);
    o_st.set(v_y.clone(), Phase::Done);
    let w_st = o_st.writes();
    for (k, v) in w_st {
        s.dirty_Task.push(k.0);
        s.st.set(k, v);
    }
    Ok(())
}

// c_tell
fn out0(s: &mut S, out: &mut Vec<Action>) -> Result<bool, StepError> {
    if !((ixsome_telling(s)? && ((((&s.st)).get(&ixfirst_telling(s)?) == Phase::Done) && !s.waiters.is_empty((ixfirst_telling(s)?).0)))) {
        return Ok(false);
    }
    #[cfg(feature = "firing")]
    FIRING.store(1, core::sync::atomic::Ordering::Relaxed);
    let act = Action::Tell(s.waiters.head((ixfirst_telling(s)?).0)?, ixfirst_telling(s)?);
    let mut o_st = Ov::over(&s.st);
    if (((&s.missing)).get(&s.waiters.head((ixfirst_telling(s)?).0)?) == 1i128) {
        o_st.set(s.waiters.head((ixfirst_telling(s)?).0)?, Phase::Queued);
    } else {
    }
    let w_st = o_st.writes();
    let mut a_waiters: Vec<AdjOp<Task>> = Vec::new();
    a_waiters.push(AdjOp::Pop((ixfirst_telling(s)?).0));
    let mut o_missing = Ov::over(&s.missing);
    o_missing.set(s.waiters.head((ixfirst_telling(s)?).0)?, rt::int2nat(rt::sub(((&s.missing)).get(&s.waiters.head((ixfirst_telling(s)?).0)?), 1i128)?)?);
    let w_missing = o_missing.writes();
    let n_depth = (s.depth.clone()).max(rt::count((rt::cons(s.waiters.head((ixfirst_telling(s)?).0)?, rt::tail(s.waiters.to_vec((ixfirst_telling(s)?).0))?)).len())?);
    for op in a_waiters {
        s.dirty_Task.push(op.id());
        s.waiters.apply(op)?;
    }
    for (k, v) in w_st {
        s.dirty_Task.push(k.0);
        s.st.set(k, v);
    }
    for (k, v) in w_missing {
        s.missing.set(k, rt::fit(v, 0, 4294967295, "missing")?);
    }
    s.depth = rt::fit(n_depth, 0, 4294967295, "depth")?;
    out.push(act);
    Ok(true)
}

// c_drop
fn out1(s: &mut S, out: &mut Vec<Action>) -> Result<bool, StepError> {
    if !((ixsome_droppable(s)? && ((((&s.st)).get(&ixfirst_droppable(s)?) == Phase::Done) && s.waiters.is_empty((ixfirst_droppable(s)?).0)))) {
        return Ok(false);
    }
    #[cfg(feature = "firing")]
    FIRING.store(2, core::sync::atomic::Ordering::Relaxed);
    let act = Action::Drop(ixfirst_droppable(s)?);
    let mut o_label = Ov::over(&s.label);
    o_label.set(ixfirst_droppable(s)?, 0i128);
    let w_label = o_label.writes();
    let mut o_st = Ov::over(&s.st);
    o_st.set(ixfirst_droppable(s)?, Phase::Free);
    let w_st = o_st.writes();
    let mut o_rank = Ov::over(&s.rank);
    o_rank.set(ixfirst_droppable(s)?, Vec::new());
    let w_rank = o_rank.writes();
    let mut o_made = Ov::over(&s.made);
    o_made.set(m_keyof(((&s.label)).get(&ixfirst_droppable(s)?))?, 0i128);
    let w_made = o_made.writes();
    for (k, v) in w_label {
        s.label.set(k, rt::fit(v, 0, 4294967295, "label")?);
    }
    for (k, v) in w_st {
        s.dirty_Task.push(k.0);
        s.st.set(k, v);
    }
    for (k, v) in w_rank {
        s.dirty_Task.push(k.0);
        s.rank.set(k, v);
    }
    for (k, v) in w_made {
        s.made.set(k, rt::fit(v, 0, 4294967295, "made")?);
    }
    out.push(act);
    Ok(true)
}

// c_start
fn out2(s: &mut S, out: &mut Vec<Action>) -> Result<bool, StepError> {
    if !((ixsome_queue(s)? && (((&s.st)).get(&ixfirst_queue(s)?) == Phase::Queued))) {
        return Ok(false);
    }
    #[cfg(feature = "firing")]
    FIRING.store(3, core::sync::atomic::Ordering::Relaxed);
    let act = Action::Start(ixfirst_queue(s)?);
    let mut o_st = Ov::over(&s.st);
    o_st.set(ixfirst_queue(s)?, Phase::Running);
    let w_st = o_st.writes();
    for (k, v) in w_st {
        s.dirty_Task.push(k.0);
        s.st.set(k, v);
    }
    out.push(act);
    Ok(true)
}

const OUTS: [fn(&mut S, &mut Vec<Action>) -> Result<bool, StepError>; 3] = [out0, out1, out2];

/// The output summands' labels, in policy order (docs/spec.md §3.11.6).
pub const OUTPUT_LABELS: [&str; 3] = ["c_tell", "c_drop", "c_start"];

/// The index plus one, in [`OUTPUT_LABELS`], of the output summand fired last; 0:
/// none (docs/spec.md §3.11.6). Process-wide; written only with the feature `firing`.
#[cfg(feature = "firing")]
pub static FIRING: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);

/// The label of the output summand fired last, read from any thread; `None`
/// without the feature `firing` or before the first fire (docs/spec.md §3.11.6).
pub fn firing() -> Option<&'static str> {
    #[cfg(feature = "firing")]
    {
        let i = FIRING.load(core::sync::atomic::Ordering::Relaxed);
        return usize::try_from(i).ok().and_then(|i| i.checked_sub(1)).and_then(|i| OUTPUT_LABELS.get(i)).copied();
    }
    #[cfg(not(feature = "firing"))]
    None
}

/// The output loop (docs/spec.md §3.8.3): the first enabled output in policy
/// order, until none is.
fn run_loop(s: &mut S, out: &mut Vec<Action>) -> Result<(), StepError> {
    let mut n: u32 = 0;
    loop {
        let mut fired = false;
        for f in OUTS {
            if f(s, out)? {
                fired = true;
                break;
            }
        }
        if !fired {
            return Ok(());
        }
        refresh(s)?;
        n = n.saturating_add(1);
        if n >= 1 << 24 {
            return Err(StepError::StepLimit);
        }
    }
}

fn state_bytes(s: &S, out: &mut Vec<u8>) {
    codec::nat(*(&s.cap), out);
    codec::nat(*(&s.nt), out);
    {
        let f = &s.label;
        codec::nat(*(f.default_value()), out);
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            codec::nat(*(v), out);
        }
    }
    {
        let f = &s.st;
        enc_Phase(f.default_value(), out);
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            enc_Phase(v, out);
        }
    }
    {
        let f = &s.rank;
        codec::len((f.default_value()).len(), out);
        for x2 in (f.default_value()).iter() {
            codec::nat(*(x2), out);
        }
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            codec::len((v).len(), out);
            for x3 in (v).iter() {
                codec::nat(*(x3), out);
            }
        }
    }
    {
        let f = &s.waiters;
        codec::len((&f.d).len(), out);
        for x4 in (&f.d).iter() {
            codec::nat(i128::from((x4).0), out);
        }
        let ents = f.entries();
        codec::len(ents.len(), out);
        for (k, v) in ents.iter() {
            let k = &Task(*k);
            codec::nat(i128::from((k).0), out);
            codec::len((v).len(), out);
            for x5 in (v).iter() {
                codec::nat(i128::from((x5).0), out);
            }
        }
    }
    {
        let f = &s.missing;
        codec::nat(*(f.default_value()), out);
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            codec::nat(i128::from((k).0), out);
            codec::nat(*(v), out);
        }
    }
    {
        let f = &s.made;
        codec::nat(*(f.default_value()), out);
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            enc_Key(k, out);
            codec::nat(*(v), out);
        }
    }
    codec::nat(*(&s.depth), out);
}

/// The stepper of the refined Core (docs/spec.md §3.8.1, §3.8.2, §3.11.2).
#[derive(Debug, Clone)]
pub struct State {
    s: S,
}

impl State {
    pub fn new(config: Config, out: &mut Vec<Action>) -> Result<State, StepError> {
        State::new_with(config, out, |_| {})
    }

    /// The constructor with the initial state changed first, for tests that start
    /// from another initial state.
    #[doc(hidden)]
    pub fn new_with(config: Config, out: &mut Vec<Action>, f: impl FnOnce(&mut S)) -> Result<State, StepError> {
        let mut s = initial(&config)?;
        f(&mut s);
        stepper_init(&mut s)?;
        run_loop(&mut s, out)?;
        Ok(State { s })
    }

    pub fn step(&mut self, event: &Event, out: &mut Vec<Action>) -> Result<(), StepError> {
        let s = &mut self.s;
        match event {
            Event::Finish(a0) => {
                if let Some(env) = match_s2(s, a0)? {
                    fire_s2(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Finish2(a0, a1) => {
                if let Some(env) = match_s3(s, a0, a1)? {
                    fire_s3(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Need(a0, a1) => {
                if let Some(env) = match_s1(s, a0, a1)? {
                    fire_s1(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Open(a0) => {
                if let Some(env) = match_s0(s, a0)? {
                    fire_s0(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
        }
        refresh(s)?;
        run_loop(s, out)
    }

    /// An estimate of the memory the state holds (§3.13.4).
    pub fn bytes(&self) -> usize {
        let mut b = Vec::new();
        state_bytes(&self.s, &mut b);
        b.len()
    }

    /// Every parameter's value, encoded as entries are (for comparing the backends).
    pub fn state_bytes(&self) -> Vec<u8> {
        let mut b = Vec::new();
        state_bytes(&self.s, &mut b);
        b
    }

    /// The state, for tests.
    pub fn state(&self) -> &S {
        &self.s
    }

    /// The members of an index in its order, for tests.
    pub fn index(&self, name: &str) -> Option<Vec<u32>> {
        match name {
            "telling" => Some(self.s.ix_telling.ordered()),
            "droppable" => Some(self.s.ix_droppable.ordered()),
            "queue" => Some(self.s.ix_queue.ordered()),
            _ => None,
        }
    }
}

